import { useState } from 'react'
import {
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogBody,
  DialogContent,
  DialogSurface,
  DialogTitle,
  DialogTrigger,
  Field,
  Input,
  MessageBar,
  Textarea,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import type { Card } from '../../hooks/useBoard'
import { useUpdateCard } from '../../hooks/useUpdateCard'
import { useDeleteCard } from '../../hooks/useDeleteCard'

const useStyles = makeStyles({
  fields: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalM,
  },
})

interface CardDetailDialogProps {
  card: Card
  open: boolean
  onClose: () => void
  initialConfirmDelete?: boolean
}

export default function CardDetailDialog({ card, open, onClose, initialConfirmDelete }: CardDetailDialogProps) {
  const styles = useStyles()
  const [title, setTitle] = useState(card.title)
  const [description, setDescription] = useState(card.description ?? '')
  const [dueDate, setDueDate] = useState(card.dueDate ?? '')
  const [clearDueDate, setClearDueDate] = useState(false)
  const [confirmDelete, setConfirmDelete] = useState(initialConfirmDelete ?? false)

  const updateCard = useUpdateCard()
  const deleteCard = useDeleteCard()

  const handleSave = () => {
    updateCard.mutate(
      {
        boardId: card.boardId,
        cardId: card.id,
        title,
        description: description || null,
        clearDueDate,
        dueDate: clearDueDate ? null : (dueDate || null),
      },
      { onSuccess: onClose },
    )
  }

  const handleDelete = () => {
    deleteCard.mutate(
      { boardId: card.boardId, cardId: card.id },
      { onSuccess: onClose },
    )
  }

  const isMutating = updateCard.isPending || deleteCard.isPending
  const hasError = updateCard.isError || deleteCard.isError

  if (confirmDelete) {
    return (
      <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
        <DialogSurface>
          <DialogBody>
            <DialogTitle>Delete card?</DialogTitle>
            <DialogContent>
              This will permanently delete "{card.title}". This action cannot be undone.
            </DialogContent>
            <DialogActions>
              <Button
                appearance="primary"
                onClick={handleDelete}
                disabled={isMutating}
              >
                Confirm
              </Button>
              <Button appearance="subtle" onClick={() => setConfirmDelete(false)}>
                Cancel
              </Button>
            </DialogActions>
          </DialogBody>
        </DialogSurface>
      </Dialog>
    )
  }

  return (
    <Dialog open={open} onOpenChange={(_, d) => { if (!d.open) onClose() }}>
      <DialogSurface>
        <DialogBody>
          <DialogTitle>Edit card</DialogTitle>
          <DialogContent>
            {hasError && (
              <MessageBar role="alert" intent="error">
                Failed to save changes. Please try again.
              </MessageBar>
            )}
            <div className={styles.fields}>
              <Field label="Title" required>
                <Input
                  aria-label="Title"
                  value={title}
                  onChange={(_, d) => setTitle(d.value)}
                />
              </Field>
              <Field label="Description">
                <Textarea
                  aria-label="Description"
                  value={description}
                  onChange={(_, d) => setDescription(d.value)}
                />
              </Field>
              <Field label="Due date">
                <Input
                  aria-label="Due date"
                  type="date"
                  value={clearDueDate ? '' : dueDate}
                  onChange={(_, d) => setDueDate(d.value)}
                  disabled={clearDueDate}
                />
              </Field>
              <Checkbox
                label="Clear due date"
                checked={clearDueDate}
                onChange={(_, d) => setClearDueDate(!!d.checked)}
              />
            </div>
          </DialogContent>
          <DialogActions>
            <Button
              appearance="primary"
              onClick={handleSave}
              disabled={isMutating}
            >
              Save
            </Button>
            <Button
              appearance="outline"
              onClick={() => setConfirmDelete(true)}
              disabled={isMutating}
            >
              Delete card
            </Button>
            <DialogTrigger disableButtonEnhancement>
              <Button appearance="subtle">
                Cancel
              </Button>
            </DialogTrigger>
          </DialogActions>
        </DialogBody>
      </DialogSurface>
    </Dialog>
  )
}

import { useState } from 'react'
import { Button, Title2, makeStyles, tokens } from '@fluentui/react-components'
import type { Card, Lane as LaneData } from '../../hooks/useBoard'
import type { BoardRole } from '../../hooks/useBoards'
import CardItem from './CardItem'
import AddCardForm from './AddCardForm'
import CardDetailDialog from './CardDetailDialog'

const useStyles = makeStyles({
  lane: {
    minWidth: '260px',
    maxWidth: '320px',
    backgroundColor: tokens.colorNeutralBackground2,
    borderRadius: tokens.borderRadiusMedium,
    padding: tokens.spacingVerticalM,
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalS,
  },
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  cards: {
    display: 'flex',
    flexDirection: 'column',
    gap: tokens.spacingVerticalXS,
  },
  emptySlot: {
    height: '40px',
    borderRadius: tokens.borderRadiusMedium,
    border: `1px dashed ${tokens.colorNeutralStroke2}`,
  },
})

interface LaneProps {
  lane: LaneData
  callerRole: BoardRole
  onDelete: (boardId: string, laneId: string) => void
}

export default function Lane({ lane, callerRole, onDelete }: LaneProps) {
  const styles = useStyles()
  const canModify = callerRole === 'Owner' || callerRole === 'Member'
  const [editingCard, setEditingCard] = useState<Card | null>(null)
  const [deletingCard, setDeletingCard] = useState<Card | null>(null)

  const sortedCards = [...lane.cards].sort((a, b) => a.position - b.position)

  return (
    <section className={styles.lane} aria-label={`Lane: ${lane.name}`}>
      <div className={styles.header}>
        <Title2 as="h2">{lane.name}</Title2>
        {canModify && (
          <Button
            size="small"
            appearance="subtle"
            aria-label={`Delete lane ${lane.name}`}
            onClick={() => onDelete(lane.boardId, lane.id)}
          >
            Delete
          </Button>
        )}
      </div>
      <div className={styles.cards}>
        {sortedCards.length === 0 && !canModify && (
          <div className={styles.emptySlot} aria-hidden="true" />
        )}
        {sortedCards.map((card) => (
          <CardItem
            key={card.id}
            card={card}
            callerRole={callerRole}
            onEdit={setEditingCard}
            onDelete={setDeletingCard}
          />
        ))}
      </div>
      {canModify && <AddCardForm boardId={lane.boardId} laneId={lane.id} />}
      {editingCard && (
        <CardDetailDialog
          card={editingCard}
          open={true}
          onClose={() => setEditingCard(null)}
        />
      )}
      {deletingCard && (
        <CardDetailDialog
          card={deletingCard}
          open={true}
          onClose={() => setDeletingCard(null)}
          initialConfirmDelete={true}
        />
      )}
    </section>
  )
}

import { useMutation, useQueryClient } from '@tanstack/react-query'
import type { ApiError } from './useBoards'
import type { Card } from './useBoard'

interface UpdateCardVars {
  boardId: string
  cardId: string
  title?: string | null
  description?: string | null
  clearDueDate: boolean
  dueDate?: string | null
}

async function updateCard(vars: UpdateCardVars): Promise<Card> {
  const response = await fetch(`/api/v1/boards/${vars.boardId}/cards/${vars.cardId}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      title: vars.title ?? null,
      description: vars.description ?? null,
      clearDueDate: vars.clearDueDate,
      dueDate: vars.dueDate ?? null,
    }),
  })
  if (!response.ok) {
    const body = await response.json().catch(() => ({}))
    throw { status: response.status, code: body.code, title: body.title } as ApiError
  }
  return response.json() as Promise<Card>
}

export function useUpdateCard() {
  const queryClient = useQueryClient()
  return useMutation<Card, ApiError, UpdateCardVars>({
    mutationFn: updateCard,
    onSettled: (_data, _error, { boardId }) =>
      queryClient.invalidateQueries({ queryKey: ['boards', boardId] }),
    retry: false,
  })
}

import { test, expect } from '@playwright/test'
import { ADMIN_AUTH, API_BASE, WEB_BASE } from '../auth.helpers'

// ── US2: Board member adds and manages cards ──────────────────────────────────

test.describe('US2: Board member adds and manages cards', () => {
  test.use({ storageState: ADMIN_AUTH })

  test('scenario 1 — member adds a card to a lane and it appears', async ({ page, request }) => {
    const boardName = `Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    expect(boardResp.ok()).toBeTruthy()
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'To Do' },
    })
    expect(laneResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByRole('heading', { name: boardName })).toBeVisible()

    await page.getByRole('button', { name: /add card/i }).first().click()
    await page.getByRole('textbox', { name: /card title/i }).fill('My First Card')
    await page.getByRole('button', { name: /^add$/i }).click()

    await expect(page.getByText('My First Card')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 2 — member updates title, description, and due date', async ({
    page,
    request,
  }) => {
    const boardName = `Update Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Original Title' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Original Title')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    await page.getByRole('textbox', { name: /title/i }).fill('Updated Title')
    await page.getByRole('textbox', { name: /description/i }).fill('A new description')
    await page.getByRole('button', { name: /save/i }).click()

    await expect(page.getByText('Updated Title')).toBeVisible({ timeout: 10_000 })
  })

  test('scenario 3 — member explicitly clears a card due date', async ({ page, request }) => {
    const boardName = `Due Date Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    const cardResp = await request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Task With Due Date', dueDate: '2099-12-31' } },
    )
    expect(cardResp.ok()).toBeTruthy()

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Task With Due Date')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    await page.getByRole('checkbox', { name: /clear due date/i }).check()
    await page.getByRole('button', { name: /save/i }).click()
    // Fluent UI Dialog sets aria-hidden on all content outside it while open.
    // Wait for the dialog to fully close before re-opening it, otherwise
    // getByRole finds 0 buttons (they are aria-hidden behind the modal).
    await expect(page.getByRole('dialog')).not.toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /edit card/i }).first().click()
    const dueDateField = page.getByRole('textbox', { name: /due date/i })
    await expect(dueDateField).toHaveValue('')
  })

  test('scenario 4 — delete card leaves remaining positions gapless', async ({
    page,
    request,
  }) => {
    const boardName = `Delete Card Board ${Date.now()}`
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, { data: { name: boardName } })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Work' },
    })
    const lane = await laneResp.json()
    for (const title of ['Card Alpha', 'Card Beta', 'Card Gamma']) {
      const resp = await request.post(
        `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
        { data: { title } },
      )
      expect(resp.ok()).toBeTruthy()
    }

    await page.goto(`${WEB_BASE}/boards/${board.id}`)
    await expect(page.getByText('Card Alpha')).toBeVisible({ timeout: 10_000 })

    await page.getByRole('button', { name: /delete card/i }).first().click()
    await page.getByRole('button', { name: /confirm/i }).click()
    await expect(page.getByRole('dialog')).not.toBeVisible({ timeout: 10_000 })

    await expect(page.getByText('Card Alpha')).not.toBeVisible()
    await expect(page.getByText('Card Beta')).toBeVisible()
    await expect(page.getByText('Card Gamma')).toBeVisible()

    // Verify gapless positions via API
    const boardDetailResp = await request.get(`${API_BASE}/api/v1/boards/${board.id}`)
    const boardDetail = await boardDetailResp.json()
    const positions = boardDetail.lanes[0].cards.map((c: { position: number }) => c.position)
    expect(positions).toEqual([1, 2])
  })

  test('scenario 5 — viewer role add-card request returns 403', async ({ request, browser }) => {
    const viewerEmail = `e2e-viewer-${Date.now()}@example.com`

    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Viewer Forbidden Board ${Date.now()}` },
    })
    const board = await boardResp.json()
    const laneResp = await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, {
      data: { name: 'Lane' },
    })
    const lane = await laneResp.json()

    // Add viewer to the board via dev seed endpoint (implemented alongside CardEndpoints)
    const seedResp = await request.post(`${API_BASE}/api/v1/dev/seed-board-member`, {
      data: { email: viewerEmail, boardId: board.id, role: 'Viewer' },
    })
    expect(seedResp.ok()).toBeTruthy()

    const viewerCtx = await browser.newContext()
    const viewerPage = await viewerCtx.newPage()
    await viewerPage.goto(
      `${API_BASE}/api/v1/dev/authenticate?email=${encodeURIComponent(viewerEmail)}&displayName=Viewer+User`,
    )
    await viewerPage.waitForURL(`${WEB_BASE}/**`)

    const forbiddenResp = await viewerPage.request.post(
      `${API_BASE}/api/v1/boards/${board.id}/lanes/${lane.id}/cards`,
      { data: { title: 'Viewer Should Not Create This' } },
    )
    expect(forbiddenResp.status()).toBe(403)

    await viewerCtx.close()
  })

  test('scenario 6 — empty card title is rejected with validation error', async ({
    page,
    request,
  }) => {
    const boardResp = await request.post(`${API_BASE}/api/v1/boards`, {
      data: { name: `Title Val Board ${Date.now()}` },
    })
    const board = await boardResp.json()
    await request.post(`${API_BASE}/api/v1/boards/${board.id}/lanes`, { data: { name: 'Lane' } })

